CREATE OR REPLACE FUNCTION public.support_training_comparison(p_run uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF NOT public._exchange_desk_staff(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF;
WITH rows AS (SELECT *,CASE WHEN decision='enviar_link' THEN 'link_'||coalesce((SELECT a->'pedido'->>'tipo' FROM jsonb_array_elements(coalesce(agent_actions,'[]')) a WHERE a->>'acao'='preparar_link' LIMIT 1),'troca') ELSE coalesce(decision,'sem') END b, CASE WHEN replay_result->>'decision'='enviar_link' THEN 'link_'||(replay_result->>'link_type') ELSE coalesce(replay_result->>'decision','sem') END a FROM public.support_training_items WHERE run_id=p_run AND replay_status IS NOT NULL)
SELECT jsonb_build_object('before',(SELECT coalesce(jsonb_object_agg(k,n),'{}') FROM (SELECT b k,count(*) n FROM rows GROUP BY b)x),'after',(SELECT coalesce(jsonb_object_agg(k,n),'{}') FROM (SELECT a k,count(*) n FROM rows WHERE replay_status='ok' GROUP BY a)x),'pending',count(*) FILTER(WHERE replay_status IN ('pendente','processando')),'errors',count(*) FILTER(WHERE replay_status='erro'),'tokens_in',coalesce(sum((replay_result->>'tokens_in')::bigint),0),'tokens_out',coalesce(sum((replay_result->>'tokens_out')::bigint),0)) INTO r FROM rows; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.support_training_comparison(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.support_training_comparison(uuid) TO authenticated;